import {checkoutView,relatedProducts,reviewSection,productInformation,homepageHero} from './commerce.js';
import {localizedProduct} from './i18n.js';
import {socialButtons} from './engagement.js';
import {E,money,icon,button,link,field,select,textarea,checkbox,table,stat,badge,notice,empty} from './ui.js';
import {cartTotals,available,needsOTP,colours,colour,productImage,variantFor} from './core.js';
export function productCard(p,s){return `<article class="product-card"><div class="product-image"><a href="#/product/${p.id}" aria-label="View ${E(localizedProduct(s,p,'name'))}"><img src="${E(productImage(p))}" class="${p.id==='grid-runner'?'shoe':''}" alt="${E(p.color+' '+p.name)}" loading="lazy"></a><span class="featured-tag">${E(p.category)}</span><button class="heart ${s.wishlist.includes(p.id)?'is-saved':''}" data-action="wishlist" data-id="${p.id}" aria-label="${s.wishlist.includes(p.id)?'Remove from':'Add to'} wishlist">${icon('heart')}</button><button class="quick" data-action="quick-view" data-id="${p.id}">Quick view</button></div><div class="product-info"><div><a href="#/product/${p.id}">${E(localizedProduct(s,p,'name'))}</a><p>${E(p.tag)}</p></div><div class="product-price">${money(p.price)}</div></div><div class="card-buy">${button('Buy it now','buy-now-select',`data-id="${p.id}" ${!p.variants.some(v=>available(p,v.size,v.color)>0)?'disabled':''}`,'btn secondary full')}</div></article>`}
function home(s){const custom=homepageHero(s);return `${custom||`<section class="hero"><img src="assets/shoe.png" alt="White sneaker on a stone pedestal"><div class="hero-copy"><div class="eyebrow">The everyday collection / 2026</div><h1>Quiet style.<br>Everyday confidence.</h1><p>Shoes and accessories that feel like you. Nothing more. Nothing less.</p>${link('Explore the collection','/shop')}</div><div class="hero-foot">Made for your everyday rotation</div></section>`}<div class="strip"><span>${icon('truck')}Delivery across Bangladesh</span><span>${icon('bag')}Cash on delivery available</span><span>${icon('lock')}A considered shopping experience</span></div><div class="home-categories"><div class="category-row">${['All','Shoes','Bags','Wallets','Socks','Belts'].map(c=>link(c==='All'?'All essentials':c,'/shop'+(c==='All'?'':'?category='+c),'category-pill')).join('')}</div></div><section class="section"><div class="section-heading"><div><p class="eyebrow">The edit</p><h2>Everyday favourites.</h2></div>${link('View all pieces','/shop','text-link')}</div><div class="product-grid">${s.products.filter(p=>!p.archived&&p.status==='Active').map(p=>productCard(p,s)).join('')}</div></section><section class="editorial"><img src="assets/bag.png" alt="Black everyday tote bag" loading="lazy"><div class="editorial-copy"><span class="eyebrow">Less, but considered</span><h2>Carry what<br>matters.</h2><p>Thoughtful shapes. Easy combinations. The finishing details of your everyday wardrobe.</p>${link('Discover bags','/shop?category=Bags','text-link')}</div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">AELVO notes</span><h2>Good style starts with you.</h2></div>${link('Our story','/about','text-link')}</div></section>`}
function shop(s,params,isSearch=false){const cat=params.get('category')||'All',q=params.get('q')||'';let list=s.products.filter(p=>!p.archived&&p.status==='Active'&&(cat==='All'||p.category===cat)&&(!q||(p.name+' '+p.category).toLowerCase().includes(q.toLowerCase())));if(s.sort==='low')list.sort((a,b)=>a.price-b.price);if(s.sort==='high')list.sort((a,b)=>b.price-a.price);return `<section class="page"><div class="page-head"><div class="breadcrumb">Home / ${isSearch?'Search':'Collection'}</div><p class="eyebrow">The AELVO edit</p><h1>${isSearch?'Find your next favourite.':cat==='All'?'All essentials.':E(cat)+'.'}</h1><p class="muted small">${list.length} ${list.length===1?'piece':'pieces'} in this preview collection</p></div><div class="shop-layout"><aside class="filter-side"><h3>Categories</h3>${['All','Shoes','Bags','Wallets','Socks','Belts'].map(c=>`<button data-action="shop-category" data-value="${c}" class="${cat===c?'active':''}">${c==='All'?'All essentials':c}</button>`).join('')}<h3>Colour</h3><p class="small muted">Black · Cloud</p><h3>Price</h3><p class="small muted">${money(2490)} – ${money(5990)}</p></aside><div><form class="toolbar" data-form="search"><input type="search" name="q" placeholder="Search the collection" value="${E(q)}" aria-label="Search products"><button class="btn small secondary" type="submit">${icon('search')}Search</button><span class="spacer"></span><select id="sort-products" aria-label="Sort products"><option value="featured" ${s.sort==='featured'?'selected':''}>Featured</option><option value="low" ${s.sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${s.sort==='high'?'selected':''}>Price: high to low</option></select></form><div class="category-row mobile-only mb">${['All','Shoes','Bags','Wallets'].map(c=>button(c,'shop-category',`data-value="${c}"`,'category-pill '+(cat===c?'active':''))).join('')}</div><div class="product-grid">${list.length?list.map(p=>productCard(p,s)).join(''):empty('No pieces found','Try a different category or search. The demo catalogue currently includes shoes, bags and wallets.','/shop','View all essentials','search')}</div></div></div></section>`}
export function productDetail(p,s,quick=false){const c=colour(p,s.color),variants=p.variants.filter(v=>!v.archived&&(!v.color||v.color===c.id)),size=variants.some(v=>v.size===s.size)?s.size:variants[0]?.size||'One size',index=s.productPhoto||0;return `${!quick?'<section class="page"><div class="breadcrumb"><a href="#/shop">Collection</a> / '+E(p.name)+'</div>':''}<div class="product-detail"><div><div class="detail-photo"><img class="colour-image" src="${E(productImage(p,c.id,index))}" alt="${E(p.name+' — '+c.name)}"></div>${c.images?.length>1?`<div class="gallery-thumbs">${c.images.map((img,i)=>button(`<img src="${E(productImage(p,c.id,i))}" alt="${E(c.name+' photo '+(i+1))}">`,'product-photo',`data-index="${i}" aria-label="Photo ${i+1}" aria-pressed="${i===index}"`,i===index?'active':'')).join('')}</div>`:''}</div><div class="detail-copy"><span class="eyebrow">${E(p.category)} / AELVO</span><h1>${E(localizedProduct(s,p,'name'))}</h1><div class="detail-price">${money(p.price)}</div><p class="description">${E(localizedProduct(s,p,'description'))}</p><div class="line-label"><span>Colour: <strong>${E(c.name)}</strong></span><span class="muted">${available(p,size,c.id)} available</span></div><div class="colour-swatches" aria-label="Choose colour">${colours(p).map(x=>button(`<span class="swatch" style="--swatch:${E(x.hex)}"></span><span>${E(x.name)}</span>`,'select-colour',`data-id="${p.id}" data-color="${E(x.id)}" aria-pressed="${x.id===c.id}"`,'colour-option '+(x.id===c.id?'active':''))).join('')}</div><div class="line-label"><span>Size: ${E(size)}</span>${p.category==='Shoes'?button('Size guide','size-guide','','text-link'):''}</div><div class="size-list">${variants.map(v=>button(E(v.size),'select-size',`data-value="${E(v.size)}" data-id="${p.id}"`,'size-btn '+(size===v.size?'active':''))).join('')}</div><div class="buy-row"><div class="quantity">${button('−','product-qty','data-delta="-1"','')}<span id="product-qty">${s.qty}</span>${button('+','product-qty','data-delta="1"','')}</div>${button('Add to bag','add-cart',`data-id="${p.id}" data-size="${E(size)}" data-color="${E(c.id)}" ${available(p,size,c.id)<1?'disabled':''}`)}</div>${button('Buy it now','buy-now',`data-id="${p.id}" data-size="${E(size)}" data-color="${E(c.id)}" ${available(p,size,c.id)<1?'disabled':''}`,'btn full buy-now')} ${button(icon('heart')+(s.wishlist.includes(p.id)?'Saved to wishlist':'Save for later'),'wishlist',`data-id="${p.id}"`,'btn secondary full')}<div class="info-lines"><div>${icon('truck')}Delivery options are shown at checkout</div><div>${icon('return')}Review the return policy before ordering</div><div>${icon('lock')}Sample product · Interactive frontend preview</div></div></div></div>${!quick?productInformation(s,p)+reviewSection(s,p)+`<section class="product-section"><h2>Related products</h2><div class="product-grid mt">${relatedProducts(s,p).map(x=>productCard(x,s)).join('')}</div></section></section>`:''}`}
export function cartLines(s,editable=true){return s.cart.map((r,i)=>{const p=s.products.find(p=>p.id===r.id);return `<div class="cart-line"><img src="${E(productImage(p,r.color))}" alt="${E(localizedProduct(s,p,'name'))}"><div class="line-main"><h3>${E(localizedProduct(s,p,'name'))}</h3><span class="small muted">${E(colour(p,r.color).name)} · ${E(r.size)}</span>${editable?`<div><span class="quantity">${button('−','cart-qty',`data-index="${i}" data-delta="-1"`,'')}<span>${r.qty}</span>${button('+','cart-qty',`data-index="${i}" data-delta="1"`,'')}</span>${button('Remove','cart-remove',`data-index="${i}"`,'remove')}</div>`:`<p class="small muted">Quantity ${r.qty}</p>`}</div><div class="line-price">${money(p.price*r.qty)}</div></div>`}).join('')}
export function totalsHTML(s,shipping=80){const t=cartTotals(s.cart,s.products,s.coupon,shipping);return `<div class="summary-line"><span class="muted">Subtotal</span><span>${money(t.subtotal)}</span></div><div class="summary-line"><span class="muted">Discount ${s.coupon?`(${E(s.coupon)})`:''}</span><span>−${money(t.discount)}</span></div><div class="summary-line"><span class="muted">Delivery</span><span>${money(t.shipping)}</span></div><div class="summary-line total"><span>Total</span><span>${money(t.total)}</span></div>`}
function cart(s){if(!s.cart.length)return `<section class="page">${empty('Your bag is waiting.','A few considered essentials can make an everyday difference.')}</section>`;return `<section class="page"><div class="page-head"><div class="breadcrumb">Home / Shopping bag</div><h1>Your bag.</h1><p class="small muted">${s.cart.reduce((n,r)=>n+r.qty,0)} pieces, chosen by you.</p></div><div class="two-col"><div>${cartLines(s)}<div class="mt">${link('Continue shopping','/shop','text-link')}</div></div><aside class="card summary"><h3>Order summary</h3>${totalsHTML(s)}<form class="coupon-row premium-promo ${s.coupon?'applied':''}" data-form="coupon">${icon('tag')}<input name="code" placeholder="Promo code" aria-label="Promo code" value="${E(s.coupon)}"><button class="btn secondary" type="submit">Apply</button></form><p class="form-help">Try AELVO10: 10% off eligible orders over ৳2,000, up to ৳500.</p><div class="mt">${link('Continue to checkout','/checkout','btn full')}</div><p class="form-help center">Shipping shown for Dhaka. Update your area at checkout.</p></aside></div></section>`}
function checkout(s){s=checkoutView(s);if(!s.cart.length)return `<section class="page">${empty('Your bag is empty.','Choose a piece before checking out.')}</section>`;const d=s.checkoutDraft||{},phone=d.phone||s.user?.phone||'',verified=!needsOTP(s.user,phone,s.verifiedCheckoutPhone);return `<section class="page"><div class="page-head"><div class="breadcrumb">Shopping bag / Checkout</div><h1>Make it yours.</h1></div><div class="steps"><span><i>1</i>Bag</span><span class="active"><i>2</i>Details & payment</span><span><i>3</i>Confirmation</span></div><div class="two-col"><form id="checkout-form" data-form="checkout" class="stack"><div class="card"><div class="between mb"><h3 style="margin:0">Contact details</h3>${s.user?badge('Signed in') :link('Sign in','/signin','text-link')}</div>${!s.user?notice('You can continue as a guest. Verify your delivery number to place a demo order.'):notice('Your verified account number can be used without another OTP.')}<div class="field-grid mt">${field('Full name','name',d.name||s.user?.name||'','text','required autocomplete="name"')}${field('Phone number','phone',phone,'tel','required placeholder="01XXXXXXXXX or +880…" autocomplete="tel" inputmode="tel"')}${field('Email (optional)','email',d.email||'','email','autocomplete="email"')}</div><div id="verification-state" class="between mt"><span class="small">${verified?badge('Phone verified'):badge('Verification required','outline')}</span>${button(verified?'Verified':'Verify number','checkout-otp',verified?'disabled':'','btn small secondary')}</div></div><div class="card"><h3>Delivery address</h3><div class="field-grid">${select('Delivery area','area',['Inside Dhaka','Outside Dhaka'],d.area||'Inside Dhaka')}${field('City / district','city',d.city||'','text','required placeholder="Dhaka"')}${textarea('Street address','address',d.address||'','required placeholder="House, road, area"')}${textarea('Order notes (optional)','notes',d.notes||'')}</div></div><div class="card"><h3>Payment method</h3><label class="choice"><input type="radio" name="payment" value="COD" ${d.payment!=='bKash'?'checked':''}>Cash on delivery<span class="muted small">Pay when received</span></label><label class="choice"><input type="radio" name="payment" value="bKash" ${d.payment==='bKash'?'checked':''}>bKash advance review<span class="muted small">Demo submission</span></label><div id="advance-fields" ${d.payment==='bKash'?'':'hidden'}>${field('Transaction reference','reference',d.reference||'','text','placeholder="DEMO-REF"')}${notice('Sample advance requirement: ৳500. Submitting a reference leaves the advance pending review; it does not mark it paid.')}</div>${checkbox('I understand this places a sample order only.','demoConsent',d.demoConsent)}<div class="error-text" data-error></div><button class="btn full mt" type="submit">Place demo order</button><p class="form-help center">No SMS, courier booking or real payment is sent.</p></div></form><aside class="card summary"><h3>Your selection</h3>${cartLines(s,false)}<div id="checkout-totals">${totalsHTML(s,d.area==='Outside Dhaka'?130:80)}</div><div class="notice mt">${icon('lock')} Demo orders are held only in this open preview.</div></aside></div></section>`}
function confirmation(s){const o=s.lastOrder;if(!o)return `<section class="page">${empty('No new order yet.','Complete the demo checkout to see your confirmation.')}</section>`;return `<section class="page"><div class="receipt center"><div class="order-motion-pill"><span class="order-road" aria-hidden="true"></span><span class="order-truck" aria-hidden="true">${icon('truck')}</span><strong>Order recorded</strong><span class="order-tick" aria-hidden="true">${icon('check')}</span></div><div class="success-mark">${icon('check')}</div><p class="eyebrow">Your demo order is in</p><h1 class="mt">Thank you, ${E(o.customer.split(' ')[0])}.</h1><p class="muted mt">Order <strong>${E(o.id)}</strong> is ${E(o.status.toLowerCase())}.</p><div class="card mt" style="text-align:left"><div class="summary-line"><span>Order total</span><strong>${money(o.total)}</strong></div><div class="summary-line"><span>Verified payment</span><strong>${money(o.paid)}</strong></div><div class="summary-line"><span>Remaining balance</span><strong>${money(o.total-o.paid)}</strong></div><hr class="divider"><p class="small">${E(o.customer)}<br>${E(o.address)}<br>${E(o.phone)}</p></div><div class="flex mt" style="justify-content:center">${link('Track this order','/tracking?id='+o.id)}${link('Continue shopping','/shop','btn secondary')}</div><p class="form-help mt">This is a preview confirmation. No real order was submitted.</p></div></section>`}
function tracking(s,params){const id=params.get('id');const o=s.orders.find(o=>o.id===id);return `<section class="page"><div class="reading"><div class="page-head center"><span class="eyebrow">Stay in the loop</span><h1>Track your order.</h1><p class="muted">Use a demo order number, such as AEL-1024.</p></div><form class="toolbar" data-form="tracking"><input name="id" required placeholder="Order number" value="${E(id||'')}" aria-label="Order number"><button class="btn">Track order</button></form>${id&&!o?notice('We could not find this order in the preview. Check the number and try again.'):''}${o?`<div class="card"><div class="between"><h3>${E(o.id)}</h3>${badge(o.status)}</div><p class="small muted">${E(o.customer)} · ${money(o.total)}</p><div class="timeline">${['Order placed','Confirmed','Packed','In transit','Delivered'].map((t,i)=>`<div class="timeline-step ${i>(o.status==='Delivered'?4:o.status==='In Transit'?3:1)?'pending':''}"><span class="timeline-dot"></span><div><strong>${t}</strong><p>${i===0?o.date:i>(o.status==='Delivered'?4:o.status==='In Transit'?3:1)?'Awaiting update':'Sample status update'}</p></div></div>`).join('')}</div><p class="form-help">Sample tracking timeline. No live courier connection.</p></div>`:''}</div></section>`}
export function auth(s,mode='signin'){const reg=mode==='signup';return `<section class="page"><div class="auth-wrap"><div class="center"><span class="eyebrow">Your AELVO account</span><h1>${reg?'A little more you.':'Welcome back.'}</h1><p class="muted small">${reg?'Create an account to keep your favourites close.':'Your orders, addresses and favourites, in one place.'}</p></div><form class="card" data-form="${reg?'signup':'signin'}">${reg?field('Full name','name','','text','required')+field('Email / Gmail','email','','email','required autocomplete="email" placeholder="you@gmail.com"'):''}${field('Mobile number','phone','','tel','required placeholder="01XXXXXXXXX"')}${field('Password','password','','password','required minlength="8" autocomplete="off" placeholder="Demo password (8+ characters)"')}<div class="error-text" data-error></div><button class="btn full mt">${reg?'Verify number & create account':'Sign in to demo'}</button><p class="form-help">Demo number: 01700007788. Use a sample password of 8+ characters; no real authentication is performed.</p><hr class="divider">${socialButtons(s)}${button('Use the verified demo account','demo-login','','btn secondary full')}</form><p class="center small">${reg?'Already have an account?':'New to AELVO?'} ${link(reg?'Sign in':'Create an account',reg?'/signin':'/signup','text-link')}</p></div></section>`}
function account(s,tab='overview'){if(!s.user)return auth(s);const menu=[['overview','Overview','grid'],['orders','My orders','bag'],['returns','Returns','return'],['addresses','Addresses','map'],['profile','Profile & security','user']];const list=s.orders.filter(o=>o.phone===s.user.phone||o.customer===s.user.name);let content='';if(tab==='overview')content=`<h2>Hello, ${E(s.user.name.split(' ')[0])}.</h2><p class="muted mt">A place for everything you have chosen.</p><div class="stats mt">${stat('Orders',list.length,'In this preview','bag')}${stat('Wishlist',s.wishlist.length,'Saved pieces','heart')}${stat('Addresses',s.addresses.length,'Ready for next time','map')}</div><div class="card"><h3>Your latest order</h3>${list.length?`<div class="between"><div><strong>${list[0].id}</strong><p class="small muted">${list[0].date} · ${money(list[0].total)}</p></div>${badge(list[0].status)}</div><div class="order-progress"><span></span></div>${link('Track order','/tracking?id='+list[0].id,'text-link')}`:empty('Nothing here yet','Your next order will appear here.','/shop','Start exploring')}</div>`;else if(tab==='orders')content=`<h2>My orders</h2><div class="mt">${table(['Order','Date','Total','Status',''],list.map(o=>[o.id,o.date,money(o.total),badge(o.status),link('View','/tracking?id='+o.id,'btn small secondary')]))}</div>`;else if(tab==='returns')content=`<h2>Request a return</h2><p class="small muted mt">Select an order and tell us what happened.</p><form class="card mt" data-form="customer-return">${select('Order','order',list.length?list.map(o=>o.id):['AEL-1023'])}${select('Reason','reason',['Size or fit','Wrong item','Damaged item','Other'])}${textarea('Details','notes','','required placeholder="Describe the issue"')}${field('Photos (optional)','photos','','file','accept="image/*" multiple')}<div class="photo-upload-preview" id="upload-preview"></div><button class="btn">Submit demo request</button><p class="form-help">This creates a sample request for admin review. Eligibility and final policy are configured later.</p></form>`;else if(tab==='addresses')content=`<div class="between"><h2>Saved addresses</h2>${button('Add address','new-address','','btn small')}</div><div class="mt">${s.addresses.map((a,i)=>`<div class="card"><div class="between"><h3>${E(a.label)}</h3>${button('Edit','edit-address',`data-index="${i}"`,'text-link')}</div><p class="small">${E(a.address)}<br>${E(a.phone)}</p></div>`).join('')}</div>`;else content=`<h2>Profile & security</h2><form class="card mt" data-form="profile">${field('Full name','name',s.user.name,'text','required')}${field('Email','email',s.user.email||'','email')}${field('Primary phone','phone',s.user.phone,'tel','required')}<p class="form-help">A new primary number must be verified before it replaces your current verified number.</p><div class="error-text" data-error></div><button class="btn mt">Save profile</button></form><div class="card"><h3>Account access</h3>${notice('This preview uses a demo session. Real password changes and secure sessions belong to the PHP backend phase.')}${button('Sign out','logout','','btn secondary mt')}</div>`;return `<section class="page"><div class="breadcrumb">Home / My account</div><div class="account-layout"><aside class="account-nav">${menu.map(([id,t,i])=>link(icon(i)+t,'/account'+(id==='overview'?'':'/'+id),tab===id?'active':'')).join('')}</aside><div>${content}</div></div></section>`}
function help(){return `<section class="page"><div class="reading"><div class="page-head"><p class="eyebrow">Here to help</p><h1>A few useful answers.</h1></div><div class="faq">${[['How do I place an order?','Choose a product and size, add it to your bag, and continue to checkout. In this preview, orders are simulated.'],['Do I need an account?','You can check out as a guest after verifying the order phone number. Guest verification does not create an account.'],['When do I verify my number?','Signup requires verification. At checkout, signed-in customers using their verified account number skip a new OTP; guests and different order numbers need verification.'],['How does cash on delivery work?','The remaining amount after verified advance payments is collected on delivery. Advance requirements can depend on the store rules.'],['How can I track or return an order?','Use Track an order for the sample timeline. Return requests are available in your account and go through receipt, inspection and refund review.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="mt">${link('Still need help? Contact us','/contact','text-link')}</div></div></section>`}
function contact(){return `<section class="page"><div class="reading"><div class="page-head"><p class="eyebrow">Let’s talk</p><h1>We’re listening.</h1><p class="muted">A question, an idea, or something that needs our attention.</p></div><form class="card report-form" data-form="contact"><div class="report-icon">${icon('mail')}</div><div class="field-grid">${field('Your name','name','','text','required')}${field('Email','email','','email','required')}${select('Topic','topic',['Order question','Product question','Bug report','Other'])}${field('Order number (optional)','order')}</div>${textarea('Message','message','','required placeholder="Tell us a little more…"')}${field('Attachment (optional)','attachment','','file','accept="image/*"')}<div class="file-feedback" aria-live="polite"></div><button class="btn">Submit demo message</button><p class="form-help">No message is sent outside this preview.</p></form></div></section>`}
function about(){return `<section class="page"><div class="reading"><p class="eyebrow">AELVO Fashion</p><h1 style="font-size:54px;font-weight:400;margin:25px 0">The everyday,<br>considered.</h1><img src="assets/bag.png" alt="A black everyday bag" style="height:360px;object-fit:cover;margin-bottom:30px"><p>We are building a place for shoes and accessories that fit naturally into your day. AELVO brings a simple point of view to the details you choose.</p><p>Explore the first collection of shoes, bags and wallets. This is our design preview; final product information and store policies will be added before launch.</p>${link('Explore the collection','/shop')}</div></section>`}
export function storefront(path,params,s){const parts=path.split('/').filter(Boolean);if(path==='/')return home(s);if(parts[0]==='shop'||parts[0]==='search')return shop(s,params,parts[0]==='search');if(parts[0]==='product'){const p=s.products.find(p=>p.id===parts[1]&&!p.archived);return p?productDetail(p,s):notFound();}if(path==='/cart')return cart(s);if(path==='/checkout')return checkout(s);if(path==='/confirmation')return confirmation(s);if(path==='/tracking')return tracking(s,params);if(path==='/wishlist')return `<section class="page"><div class="page-head"><p class="eyebrow">Keep them close</p><h1>Your wishlist.</h1></div><div class="product-grid">${s.wishlist.length?s.products.filter(p=>s.wishlist.includes(p.id)).map(p=>productCard(p,s)).join(''):empty('A little inspiration, saved.','Tap the heart on a piece to find it here later.','/shop','Explore the collection','heart')}</div></section>`;if(path==='/signin'||path==='/signup')return auth(s,parts[0]);if(parts[0]==='account')return account(s,parts[1]);if(path==='/help')return help();if(path==='/contact')return contact();if(path==='/about')return about();if(parts[0]==='policy')return `<section class="page"><div class="reading"><div class="page-head"><span class="eyebrow">Store information</span><h1>${E((parts[1]||'Store').replace(/^./,c=>c.toUpperCase()))} policy</h1></div>${notice('Policy content is awaiting business review. This page demonstrates the selected layout and does not set live purchase terms.')}<h2>Before launch</h2><p>The store’s final shipping charges, return eligibility, refund conditions and contact details will appear here once approved.</p>${link('Contact AELVO','/contact','text-link')}</div></section>`;return notFound()}
export const notFound=()=>`<section class="page"><div class="empty"><p class="eyebrow">404 / A small detour</p><h1 style="font-size:64px;margin:20px 0">Nothing here.</h1><p>The page you are looking for has moved, or doesn’t exist.</p>${link('Back to the collection','/shop')}${link('Home','/','btn ghost')}</div></section>`;
